import type { HeadFC } from "gatsby"
import React from "react"

import PageLayout from "../components/layouts/PageLayout"
import PageHeader from "../components/shared/PageHeader"
import SEO from "../components/shared/SEO"
import { soundPlaceholders } from "../data/sound"

const SoundPage = (): React.ReactElement => {
  return (
    <PageLayout className="sound-page">
      <PageHeader
        description="Music, production, and sound experiments. This space is being prepared for the first release."
        title="Sound Creations"
      />

      <section aria-label="Sound projects" className="sound-grid">
        {soundPlaceholders.map((item, index) => (
          <article className="sound-card" key={item.title}>
            <div aria-hidden="true" className="sound-card-art">
              <span>{String(index + 1).padStart(2, "0")}</span>
              <span className="sound-card-wave">∿ ∿ ∿</span>
            </div>
            <div className="sound-card-copy">
              <p className="sound-card-meta">{item.type}</p>
              <h2>{item.title}</h2>
              <p>{item.description}</p>
            </div>
          </article>
        ))}
      </section>

      <p className="sound-note">
        Sound will go live when the first tracks are ready. The placeholders above can
        be replaced with players, cover art, and links to SoundCloud or Spotify.
      </p>
    </PageLayout>
  )
}

export default SoundPage

export const Head: HeadFC = () => (
  <SEO
    description="Music, production, and sound experiments by Ejeh Daniel."
    pathname="/sound"
    title="Sound"
  />
)
